export function renderSummary(result: GateResult): string {
  const hasStructureIssue = result.findings.some((f) => f.checkId === 'structure');
  if (hasStructureIssue) {
    return 'BLOCK 0/7: structure';
  }

  const checkIds = GATE_CHECKS.map((c) => c.id);
  const checksWithBlocks = new Set<string>();

  for (const finding of result.findings) {
    if (finding.severity === 'block') {
      checksWithBlocks.add(finding.checkId);
    }
  }

  const answered = checkIds.length - checksWithBlocks.size;
  const total = checkIds.length;

  if (checksWithBlocks.size === 0) {
    return `${result.verdict} ${answered}/${total}`;
  }

  const blockedIds = checkIds.filter((id) => checksWithBlocks.has(id)).join(', ');
  return `${result.verdict} ${answered}/${total}: ${blockedIds}`;
}

